/* ---------- 4. WRITING ---------- */
const FINAL={'ך':'כ','ם':'מ','ן':'נ','ף':'פ','ץ':'צ'};
/* letters that sound alike are never offered against each other (except a final letter against its regular form, on purpose) */
const GRP=['אעה','בו','כךחק','טת','סש','צץ','מם','נן','פף','ג','ד','ז','י','ל','ר'];
const grp=c=>GRP.findIndex(g=>g.includes(c));
const sameSound=(a,b)=>grp(a)===grp(b);
const DIST='בגדזלמנרתפסקשצ'.split('');
const hash=s=>{let x=7;for(const c of s)x=(x*31+c.charCodeAt(0))%100003;return x;};
const bare=w=>letters(w).map(x=>x.c).join('');
const plainSet=new Set(words.map(x=>bare(x.w)));
/* missing letter: the final letter when it has a final form (options: final, regular, another), else the first clear consonant */
function missOf(wd){const L=letters(wd.w);const last=L.length-1;let i=-1,opts;
  if(FINAL[L[last].c]&&L.length>1){i=last;}
  else{for(let k=0;k<L.length;k++){const x=L[k],c=x.c;const vowelLetter=(c==='ו'&&(/[ֹּ]/.test(x.m))&&!vowOf(x.m).filter(v=>v!=='o').length&&k>0)||(c==='י'&&!x.m)||(k===last&&/[אה]/.test(c)&&!x.m);
    if(vowelLetter||/[אהעשׂ]/.test(c)||x.m.includes('ׁ')||x.m.includes('ׂ'))continue;i=k;break;}}
  if(i<0)return null;const ans=L[i].c;const h=hash(wd.w);
  const others=DIST.filter(c=>!sameSound(c,ans)&&!(FINAL[ans]&&sameSound(c,FINAL[ans])));
  const pickO=n=>{const out=[];for(let k=0;out.length<n&&k<others.length;k++){const c=others[(h+k*5)%others.length];if(!out.includes(c)){const cand=L.map((x,j)=>j===i?c:x.c).join('');if(!plainSet.has(cand))out.push(c);}}return out;};
  opts=FINAL[ans]?[ans,FINAL[ans],...pickO(1)]:[ans,...pickO(2)];
  const show=L.map((x,j)=>j===i?'◌'+x.m:x.c+x.m).join('');
  return {lv:wd.lv,w:wd.w,i,show,ans,opts,pic:wd.pic};}
/* build a sentence from its words, in order (short subject-verb-object sentences with one natural order) */
